function numberChecker(number) {
  if (number === 6) {
    return false;
  } else {
    return true;
  }
  switch (number) {
    case number === 1000:
      return true;
      break;
    case number === 10:
      return true;
      break;  
    default:
      return false;
  }
}

// Do not edit below this line
module.exports = numberChecker;
